CREATE DATABASE IF NOT EXISTS sms_management;
USE sms_management;
CREATE TABLE students(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,class_name VARCHAR(30),phone VARCHAR(20),email VARCHAR(120),status VARCHAR(20));
CREATE TABLE employees(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,designation VARCHAR(100),department VARCHAR(100),phone VARCHAR(20),status VARCHAR(20));
CREATE TABLE classes(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50),section VARCHAR(20),teacher VARCHAR(100),room VARCHAR(30),students INT);
CREATE TABLE subjects(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),code VARCHAR(30),class_name VARCHAR(30),teacher VARCHAR(100));
CREATE TABLE fees(id INT AUTO_INCREMENT PRIMARY KEY,student VARCHAR(100),class_name VARCHAR(30),type VARCHAR(80),amount DECIMAL(12,2),status VARCHAR(20),date DATE);
CREATE TABLE books(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200),author VARCHAR(120),category VARCHAR(80),qty INT,available INT);
CREATE TABLE expenses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150),category VARCHAR(80),amount DECIMAL(12,2),date DATE);
CREATE TABLE exams(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),class_name VARCHAR(30),subject VARCHAR(100),date DATE,status VARCHAR(30));
